+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final String NAME_REQUIRED = "Name is required";
+    private static final String EMAIL_INVALID = "Enter a valid e-mail address";
+    private static final String CONTACT_REQUIRED = "Give an e-mail address or a phone number";
+    private static final String MESSAGE_REQUIRED = "Message is required";
+    private static final String MESSAGE_TOO_LONG = "Message must be at most 500 characters";
+
+    private final ContactMessageService messageService;
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<ContactMessage> messagesGrid = new Grid<>(ContactMessage.class, false);
+
+    private boolean disabledUntilNextEdit;
+    private boolean formFieldHasFocus;
+    private boolean editedSinceFocusLeftForm;
+    private boolean resettingFields;
+
+    public ContactView(ContactMessageService messageService) {
+        this.messageService = messageService;
+
+        setPadding(true);
+        setSpacing(true);
+        setMaxWidth("60em");
+
+        H1 heading = new H1("Contact");
+        RouterLink aboutLink = new RouterLink("About", AboutView.class);
+
+        prepareFieldsForImmediateChangeTracking();
+
+        FormLayout form = new FormLayout();
+        form.setAutoResponsive(true);
+        form.setExpandColumns(true);
+        form.setExpandFields(true);
+        form.setWidthFull();
+        form.setMaxWidth("42em");
+        form.add(nameField, emailField, phoneField, messageField);
+
+        sendButton.addClickListener(event -> sendMessage());
+        addEditListeners();
+        Shortcuts.addShortcutListener(this, this::sendMessage, Key.ENTER)
+                .listenOn(nameField, emailField, phoneField, messageField);
+        Shortcuts.addShortcutListener(this, event -> {
+            if (formFieldHasFocus || editedSinceFocusLeftForm) {
+                sendMessage();
+            }
+        }, Key.ENTER).listenOn(UI.getCurrent()).allowBrowserDefault();
+
+        messagesGrid.addColumn(ContactMessage::name).setHeader("Name");
+        messagesGrid.addColumn(ContactMessage::message).setHeader("Message");
+        messagesGrid.setItems(messageService.getNewestFirst());
+        messagesGrid.setWidthFull();
+
+        HorizontalLayout actions = new HorizontalLayout(sendButton);
+        actions.setWidthFull();
+
+        add(heading, aboutLink, form, actions, messagesGrid);
+        setWidthFull();
+    }
+
+    private void prepareFieldsForImmediateChangeTracking() {
+        nameField.setValueChangeMode(ValueChangeMode.EAGER);
+        emailField.setValueChangeMode(ValueChangeMode.EAGER);
+        emailField.setManualValidation(true);
+        phoneField.setValueChangeMode(ValueChangeMode.EAGER);
+        messageField.setValueChangeMode(ValueChangeMode.EAGER);
+    }
+
+    private void addEditListeners() {
+        nameField.addValueChangeListener(event -> fieldEdited());
+        emailField.addValueChangeListener(event -> fieldEdited());
+        phoneField.addValueChangeListener(event -> fieldEdited());
+        messageField.addValueChangeListener(event -> fieldEdited());
+
+        nameField.addFocusListener(event -> formFieldHasFocus = true);
+        emailField.addFocusListener(event -> formFieldHasFocus = true);
+        phoneField.addFocusListener(event -> formFieldHasFocus = true);
+        messageField.addFocusListener(event -> formFieldHasFocus = true);
+        nameField.addBlurListener(event -> fieldFocusLeftForm());
+        emailField.addBlurListener(event -> fieldFocusLeftForm());
+        phoneField.addBlurListener(event -> fieldFocusLeftForm());
+        messageField.addBlurListener(event -> fieldFocusLeftForm());
+    }
+
+    private void fieldEdited() {
+        if (!resettingFields) {
+            editedSinceFocusLeftForm = true;
+        }
+        reenableAfterEdit();
+    }
+
+    private void fieldFocusLeftForm() {
+        formFieldHasFocus = false;
+        editedSinceFocusLeftForm = false;
+    }
+
+    private void reenableAfterEdit() {
+        if (disabledUntilNextEdit) {
+            disabledUntilNextEdit = false;
+            sendButton.setEnabled(true);
+        }
+    }
+
+    private void sendMessage() {
+        if (disabledUntilNextEdit || !sendButton.isEnabled()) {
+            return;
+        }
+
+        if (!validateForm()) {
+            return;
+        }
+
+        ContactMessage sent = new ContactMessage(nameField.getValue(), emailField.getValue(),
+                phoneField.getValue(), messageField.getValue());
+        messageService.add(sent);
+        messagesGrid.setItems(messageService.getNewestFirst());
+
+        resettingFields = true;
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+        resettingFields = false;
+
+        disabledUntilNextEdit = true;
+        sendButton.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private boolean validateForm() {
+        String name = safeValue(nameField.getValue());
+        String email = safeValue(emailField.getValue());
+        String phone = safeValue(phoneField.getValue());
+        String message = safeValue(messageField.getValue());
+
+        boolean valid = true;
+
+        boolean nameBlank = name.isBlank();
+        setFieldError(nameField, nameBlank, nameBlank ? NAME_REQUIRED : "");
+        valid &= !nameBlank;
+
+        boolean emailProvided = !email.isBlank();
+        boolean phoneProvided = !phone.isBlank();
+        String emailError = "";
+        if (emailProvided && emailField.getDefaultValidator()
+                .apply(email, new ValueContext(this, emailField)).isError()) {
+            emailError = EMAIL_INVALID;
+        } else if (!emailProvided && !phoneProvided) {
+            emailError = CONTACT_REQUIRED;
+        }
+        setFieldError(emailField, !emailError.isEmpty(), emailError);
+        valid &= emailError.isEmpty();
+
+        boolean messageBlank = message.isBlank();
+        boolean messageTooLong = message.codePointCount(0, message.length()) > 500;
+        String messageError = messageBlank ? MESSAGE_REQUIRED
+                : messageTooLong ? MESSAGE_TOO_LONG : "";
+        setFieldError(messageField, !messageError.isEmpty(), messageError);
+        valid &= messageError.isEmpty();
+
+        return valid;
+    }
+
+    private static void setFieldError(TextField field, boolean invalid, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(invalid);
+    }
+
+    private static void setFieldError(EmailField field, boolean invalid, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(invalid);
+    }
+
+    private static void setFieldError(TextArea field, boolean invalid, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(invalid);
+    }
+
+    private static String safeValue(String value) {
+        return value == null ? "" : value;
+    }
+
+    private boolean hasEnteredAnything() {
+        return hasText(nameField.getValue()) || hasText(emailField.getValue())
+                || hasText(phoneField.getValue()) || hasText(messageField.getValue());
+    }
+
+    private static boolean hasText(String value) {
+        return value != null && !value.isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasEnteredAnything()) {
+            return;
+        }
+
+        ContinueNavigationAction navigation = event.postpone();
+        Dialog confirmation = new Dialog();
+        confirmation.setCloseOnEsc(false);
+        confirmation.setCloseOnOutsideClick(false);
+        confirmation.add(new NativeLabel("You have a message in progress. Discard it?"));
+
+        Button keepEditing = new Button("Keep editing", click -> {
+            confirmation.close();
+            navigation.cancel();
+        });
+        Button discard = new Button("Discard", click -> {
+            confirmation.close();
+            navigation.proceed();
+        });
+        confirmation.getFooter().add(keepEditing, discard);
+        confirmation.open();
+    }
+}
