+package com.example.contact;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+import com.microsoft.playwright.options.WaitForSelectorState;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    @Test
+    void enterSendsAndDirtyNavigationCanBeKeptOrDiscarded() {
+        Page page = getPage();
+        page.getByLabel("Name").fill("Browser Sender");
+        page.getByLabel("Phone").fill("555-0123");
+        page.getByLabel("Message").fill("Sent from Chromium");
+        page.getByLabel("Message").press("Enter");
+
+        page.getByText("Message sent").waitFor();
+        assertTrue(page.getByText("Browser Sender").isVisible());
+        assertTrue(page.getByText("Sent from Chromium").isVisible());
+        assertTrue(page.getByRole(AriaRole.BUTTON,
+                new Page.GetByRoleOptions().setName("Send")).isDisabled());
+
+        page.getByLabel("Name").fill("Draft sender");
+        Locator about = page.getByRole(AriaRole.LINK,
+                new Page.GetByRoleOptions().setName("About"));
+        about.click();
+        Locator dialog = page.locator("vaadin-dialog-overlay");
+        dialog.waitFor(new Locator.WaitForOptions().setState(WaitForSelectorState.VISIBLE));
+        page.getByText("Keep editing", new Page.GetByTextOptions().setExact(true)).click();
+        assertEquals("Draft sender", page.getByLabel("Name").inputValue());
+        assertTrue(about.isVisible());
+
+        about.focus();
+        about.press("Enter");
+        dialog.waitFor(new Locator.WaitForOptions().setState(WaitForSelectorState.VISIBLE));
+        page.getByText("Keep editing", new Page.GetByTextOptions().setExact(true)).click();
+        assertEquals("Draft sender", page.getByLabel("Name").inputValue());
+
+        about.click();
+        page.getByText("Discard", new Page.GetByTextOptions().setExact(true)).click();
+        Locator aboutHeading = page.getByRole(AriaRole.HEADING,
+                new Page.GetByRoleOptions().setName("About"));
+        aboutHeading.waitFor();
+        assertTrue(aboutHeading.isVisible());
+        page.goBack();
+        Locator sentSender = page.getByText("Browser Sender");
+        sentSender.waitFor();
+        assertTrue(sentSender.isVisible());
+        assertFalse(page.getByRole(AriaRole.BUTTON,
+                new Page.GetByRoleOptions().setName("Send")).isDisabled());
+    }
+}
