+package com.example.contact;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Autowired
+    private ContactMessageService messageService;
+
+    @Test
+    void validatesSendsAndProtectsDraftsDuringNavigation() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextField phone = $(TextField.class).withLabel("Phone").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+        Button send = $(Button.class).withText("Send").single();
+        RouterLink about = $(RouterLink.class).withText("About").single();
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertTrue(send.isEnabled());
+
+        test(send).click();
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+
+        test(name).setValue("Avery Example");
+        test(email).setValue("not-an-email");
+        test(message).setValue("A message that must remain in the form");
+        test(send).click();
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertEquals("A message that must remain in the form", message.getValue());
+
+        test(message).setValue("x".repeat(501));
+        test(email).setValue("");
+        test(phone).setValue("555-0100");
+        test(send).click();
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertTrue(messageService.getNewestFirst().isEmpty());
+
+        test(message).setValue("A message that must remain in the form");
+        fireShortcut(Key.ENTER);
+
+        assertEquals(1, messageService.getNewestFirst().size());
+        assertEquals("Avery Example", messageService.getNewestFirst().get(0).name());
+        assertEquals("A message that must remain in the form",
+                messageService.getNewestFirst().get(0).message());
+        assertTrue($(Grid.class).exists());
+        assertTrue($(com.vaadin.flow.component.notification.Notification.class).exists());
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertFalse(send.isEnabled());
+
+        test(phone).setValue("555-0199");
+        assertTrue(send.isEnabled());
+
+        test(about).click();
+        assertInstanceOf(ContactView.class, getCurrentView());
+        Dialog confirmation = $(Dialog.class).single();
+        assertTrue(test(confirmation).isOpen());
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("555-0199", phone.getValue());
+
+        test(about).click();
+        test($(Button.class).withText("Discard").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+
+        navigate(ContactView.class);
+        assertEquals(1, messageService.getNewestFirst().size());
+        assertEquals("Avery Example", messageService.getNewestFirst().get(0).name());
+
+        TextField returnedName = $(TextField.class).withLabel("Name").single();
+        EmailField returnedEmail = $(EmailField.class).withLabel("Email").single();
+        TextArea returnedMessage = $(TextArea.class).withLabel("Message").single();
+        test(returnedName).setValue("Jordan Example");
+        test(returnedEmail).setValue("jordan@example.com");
+        test(returnedMessage).setValue("Newest message");
+        test($(Button.class).withText("Send").single()).click();
+        assertEquals(2, messageService.getNewestFirst().size());
+        assertEquals("Jordan Example", messageService.getNewestFirst().get(0).name());
+        assertEquals("Avery Example", messageService.getNewestFirst().get(1).name());
+
+        test($(RouterLink.class).withText("About").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertTrue($(Dialog.class).all().stream().noneMatch(Dialog::isOpened));
+    }
+}
